func buildSubject(pattern string, values map[string]string) (string, error) {
	result := pattern
	for name, value := range values {
		if err := validateSubjectToken(name, value); err != nil {
			return "", err
		}
		result = strings.ReplaceAll(result, "{"+name+"}", value)
	}
	return result, nil
}

func validateSubjectToken(name, value string) error {
	if value == "" {
		return fmt.Errorf("subject parameter %s is empty", name)
	}
	if strings.ContainsAny(value, ".*> \t\r\n") {
		return fmt.Errorf("subject parameter %s contains a separator, wildcard, or whitespace", name)
	}
	return nil
}

